ALTER TYPE booking_event_type ADD VALUE IF NOT EXISTS 'automation.booking_recovery.recommendation_created';
CREATE TABLE IF NOT EXISTS booking_recovery_recommendations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,recovery_case_id uuid NOT NULL REFERENCES booking_recovery_cases(id) ON DELETE CASCADE,booking_id uuid NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,client_id uuid NOT NULL REFERENCES clients(id) ON DELETE CASCADE,suggested_action varchar(32) NOT NULL,suggested_priority varchar(16) NOT NULL,confidence integer NOT NULL CHECK(confidence BETWEEN 0 AND 100),rationale text NOT NULL,signals jsonb NOT NULL DEFAULT '{}'::jsonb,engine varchar(48) NOT NULL DEFAULT 'recovery_rules_v1',version integer NOT NULL DEFAULT 1,status varchar(20) NOT NULL DEFAULT 'shadow' CHECK(status IN ('shadow','accepted','adjusted','rejected')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,recovery_case_id));
CREATE INDEX IF NOT EXISTS booking_recovery_recommendations_company_status_idx ON booking_recovery_recommendations(company_id,status,updated_at);ALTER TABLE booking_recovery_recommendations ENABLE ROW LEVEL SECURITY;
